  // Keep actual model words such as Mega Strobe / Pocket Spot intact.
  title=title.replace(/^ADJ Led (?:PAR|BAR)\s*/i,'ADJ ').replace(/^RGB Spider Laser Moving head.*$/i,'Spider Laser').replace(/^RGB text and pattern Laser\s*/i,'').replace(/^Laser\s+/i,'');
  if(m.brand!=='Другие модели')for(const [,re] of brands.filter(([b])=>b===m.brand)){const match=title.match(re);if(match&&match.index===0)title=title.slice(match[0].length).trim()}
  title=title.replace(/,?\s*(?:UHD|FULL HD|Ultra HD LED)\b.*$/i,'').replace(/\s*\+.*$/,'').trim();m.catalogTitle=title||name;
  let bits=[],modeList=(m.modes||[]).map(v=>typeof v==='number'?v:v.channels).filter(Number.isFinite),color=(name+' '+JSON.stringify(m.modes||[])).match(/RGBWA\+?UV|RGBWA|RGBW|RGB|CMY|\bUV\b/i)?.[0]?.toUpperCase();
  if(m.category==='node'){bits.push(m.id==='snl-323'?'USB → DMX':deviceTypeNames[m.kind]||'DMX');if(/RDM/.test(name)||m.id==='snl-508')bits.push('RDM');if(m.outputs)bits.push(m.outputs+' OUT')}
  else if(m.kind==='laser'){const power=name.match(/\d+(?:[.,]\d+)?\s*mW/i)||name.match(/\d+(?:[.,]\d+)?\s*W\b/i);if(power)bits.push(power[0]);if(color)bits.push(color)}
  else if(m.kind==='mirrorball'){const diameter=name.match(/\d+\s*cm/i);if(diameter){m.catalogTitle='Ø '+diameter[0];if(/gold/i.test(name))m.catalogTitle+=' · золотой';if(/half/i.test(name))m.catalogTitle+=' · полусфера'}bits.push(/motor|mootor/i.test(name)?'С мотором':'Мотор не указан')}
  else {bits.push(deviceTypeNames[m.kind]||'Прибор');if(color)bits.push(color);if(['strobe','fog','haze','snow','bubble','fan','blinder'].includes(m.kind)&&Number.isFinite(m.watts))bits.push(m.watts+' W');else if(modeList.length){const lo=Math.min(...modeList),hi=Math.max(...modeList);bits.push((lo===hi?lo:lo+'–'+hi)+' CH')}else if(['tv','projector','processor','mixer','laptop','player','camera'].includes(m.kind)){if(m.video)bits.push(m.videoConnector);const diagonal=name.match(/\d+(?:\.\d+)?\s*["”″]/);if(diagonal)bits.push(diagonal[0]);else if(Number.isFinite(m.watts))bits.push(m.watts+' W')}}
