function equipmentFace(n){const {w,h}=size(n);if(['snl-508','snl-517'].includes(n.model))return `<svg class="equipment-face" viewBox="0 0 ${w} ${h}" aria-hidden="true">${[h-96,h-48].map(y=>`<rect x="24" y="${y}" width="192" height="36" rx="2" fill="#111313" stroke="#303333" stroke-width=".7"/>`).join('')}</svg>`;if(n.model==='snl-368')return '';const count=['console','node','splitter','interface','switch'].includes(n.kind)?ports(n).filter(p=>p.dy===1&&p.out&&['dmx','ethernet'].includes(p.type)).length:0;return `<svg class="equipment-face" viewBox="0 0 ${w} ${h}" aria-hidden="true">${count?`<rect x="${(w-count*G)/2}" y="${h-48}" width="${count*G}" height="36" rx="2" fill="#111313" stroke="#303333" stroke-width=".7"/>`:''}</svg>`}
