function powerWarnings(n,power){
 const warnings=[],root=RigCore.root(state,n.id,'power');
 if(n.consumes){
  if(!root&&!n.internalBattery)warnings.push('Нет питания');
  if(root&&!Number.isFinite(n.watts))warnings.push('Неизвестна мощность');
  if(root&&/typical/.test(n.wattsBasis))warnings.push('Указана типичная мощность, максимум не подтверждён');
  if(root&&n.wattsBasis==='lamp-rating')warnings.push('Указана мощность лампы, полное потребление не подтверждено');
 }
 const branches=power.branches.filter(b=>b.source===n.id);
 if(branches.some(b=>b.overload))warnings.push('Превышен лимит линии');
 if(branches.some(b=>!b.limit&&(b.watts||b.unknown)))warnings.push('Не указан допустимый бюджет мощности');
 if(branches.length&&n.kind==='outlet'&&!n.circuit)warnings.push('Не указан ID электрической линии');
 if(power.links.some(e=>e.overload&&state.edges.some(w=>w.id===e.id&&w.from===n.id)))warnings.push('Перегруз выхода');
 if(n.totalLimit&&RigCore.load(RigCore.downstream(state,n.id)).watts>n.totalLimit)warnings.push('Превышен лимит распределителя');
 return warnings;
}
