document.addEventListener('pointerdown',e=>{if(!e.target.closest('#addMenu'))closeAddMenu()});
$('#closeAddMenu').onclick=closeAddMenu;
async function importProjectFile(file){
 if(!file)return;
 const button=$('#importProject');button.disabled=true;
 try{
  const imported=normalize(JSON.parse((await file.text()).replace(/^\uFEFF/,'')));
  stopTest();remember();state=imported;
  selected=null;selection.clear();selectedEdge=null;pending=null;gesture=null;waypointMode=false;routeCache=null;
  $('#selectionBox').hidden=true;$('#modelPicker').hidden=true;
  update();fit();toast('Схема открыта · приборов: '+state.nodes.length);
 }catch(error){toast('Не удалось открыть JSON: '+error.message)}
 finally{button.disabled=false;$('#projectFile').value=''}
}
$('#importProject').onclick=()=>$('#projectFile').click();
$('#projectFile').onchange=e=>importProjectFile(e.target.files?.[0]);
function togglePlacementMode(){
 placementMode=!placementMode;pending=null;
 $('#visualizer').textContent=placementMode?'К схеме':'Размещение';
 $('#visualizer').setAttribute('aria-pressed',String(placementMode));
 if(placementMode&&$('#libraryPanel').classList.contains('collapsed'))$('#toggleLibrary').click();
 renderCatalog();renderNodes();drawWires();
}
$('#visualizer').onclick=togglePlacementMode;
$('#search').oninput=renderCatalog;$('#layer').onchange=e=>{layer=e.target.value;drawWires()};$('#consumption').onclick=()=>{showPower=!showPower;$('#consumption').classList.toggle('active',showPower);$('#consumption').setAttribute('aria-pressed',showPower);renderNodes();renderInspector();renderPhases();if(!$('#patchPanel').hidden)renderPatch()};$('#phases').onclick=()=>{showPhases=!showPhases;$('#phases').classList.toggle('active',showPhases);$('#phases').setAttribute('aria-pressed',showPhases);renderPhases();renderNodes()};$('#undo').onclick=()=>undo();$('#redo').onclick=()=>undo(true);$('#saveProject').onclick=()=>download('rig-grid-project.json',JSON.stringify(state,null,2),'application/json');$('#openPatch').onclick=renderPatch;$('.brand').onclick=e=>{e.preventDefault();fit()};
window.addEventListener('keydown',e=>{
 if(e.key==='Escape'){
  closeAddMenu();finishMove();clearMarquee();
  if(!$('#modelPicker').hidden){closeModelPicker();return}
  stopTest();pending=null;waypointMode=false;updateCableHint();drawWires();closeInspector();$('#patchPanel').hidden=true;
 }
 const target=e.target;
 if(e.defaultPrevented||target.isContentEditable||target.closest?.('input:not([type="checkbox"]):not([type="radio"]),select,textarea'))return;
 const mod=e.ctrlKey||e.metaKey;
 const key=e.key.toLowerCase();
 const shortcut=/^[a-z]$/.test(key)?key:e.code?.match(/^Key([A-Z])$/)?.[1].toLowerCase();
 if(mod){
  if(!['c','v','a','z'].includes(shortcut)||e.altKey)return;
  e.preventDefault();
  if(shortcut==='c')copySelection();
  if(shortcut==='v')pasteSelection();
  if(shortcut==='z')undo(e.shiftKey);
  if(shortcut==='a'){
   selection.clear();state.nodes.forEach(n=>selection.add(n.id));
   selected=[...selection].at(-1)||null;selectedEdge=null;renderNodes();renderInspector();
  }
  return;
 }
 if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();deleteSelection();return}
 if(e.code==='Space'&&!target.closest?.('button,input,[role="switch"]')){space=true;e.preventDefault()}
 if(shortcut==='f'){fit();e.preventDefault()}
 if(shortcut==='r'&&canRotate(node(selected)))mutate(()=>node(selected).rotation=(node(selected).rotation+90)%360);
});
window.addEventListener('keyup',e=>{if(e.code==='Space')space=false});window.addEventListener('blur',()=>{space=false;clearMarquee();finishMove()});window.addEventListener('resize',applyView);
function setupPanels(){for(const [key,panel,button,body,label] of [['library','#libraryPanel','#toggleLibrary','#libraryBody','каталог'],['inspector','#inspectorPanel','#toggleInspector','#inspector','свойства']]){let collapsed=false;try{collapsed=localStorage.getItem('rig-panel-'+key)==='collapsed'}catch{}const apply=()=>{$(panel).classList.toggle('collapsed',collapsed);$(button).setAttribute('aria-expanded',String(!collapsed));$(button).setAttribute('aria-label',(collapsed?'Развернуть ':'Свернуть ')+label);$(button).title=(collapsed?'Развернуть ':'Свернуть ')+label;$(body).inert=collapsed;};apply();$(button).onclick=()=>{collapsed=!$(panel).classList.contains('collapsed');apply();try{localStorage.setItem('rig-panel-'+key,collapsed?'collapsed':'open')}catch{}requestAnimationFrame(applyView)}}}
function showCatalogError(error){$('#catalogTree').innerHTML='<p class="verification-note">Не удалось загрузить справочник приборов. Обнови страницу.</p>';$('#inspector').innerHTML='<p class="help">'+esc(error.message)+'</p>';}
function ensureFloorArea(){
 state.areas??=[];
 if(state.areas.some(a=>a.type==='floor'||/зона пола/i.test(a.name||'')))return;
 const room=state.areas.find(a=>a.type==='room'),w=55*G,h=60*G;
 state.areas.push({id:uid(),type:'floor',name:'Зона пола',x:room?snap(room.x+(room.w-w)/2):0,y:room?snap(room.y+(room.h-h)/2):0,w,h});
}
async function init(){try{const res=await fetch('catalog-researched.json');if(!res.ok)throw Error('Не загружен полный каталог');if(res.ok){const data=await res.json(),list=Array.isArray(data)?data:data.entries||data.products||[];for(const raw of list){if(!raw.id||!categories[raw.category])continue;const existing=catalog.find(m=>m.name.toLowerCase().replace(/\W/g,'')===raw.name.toLowerCase().replace(/\W/g,''));if(existing){if(raw.source)existing.rentalSource=raw.source;continue}const kind=raw.kind||'par';catalog.push({...raw,kind,notes:Array.isArray(raw.notes)?raw.notes.join(' '):raw.notes,manual:raw.manual||raw.manufacturerSource||raw.manuals?.[0],dmxConnector:(raw.connectors||[]).filter(v=>/DMX/.test(v)).length===1?(raw.connectors.find(v=>/DMX/.test(v)).includes('5-pin')?'5-pin XLR':raw.connectors.find(v=>/DMX/.test(v)).includes('3-pin')?'3-pin XLR':''):'',label:raw.label||kind.toUpperCase(),dmx:raw.dmx===true,consumes:raw.consumes??true})}}}catch(error){showCatalogError(error);return}try{await loadVerification()}catch(error){showCatalogError(error);return}prepareCatalog();finishVerifiedCatalog();try{const saved=localStorage.getItem('rig-grid-v4');state=saved?normalize(JSON.parse(saved)):demo()}catch(err){state=demo();toast('Сохранённый проект не открыт: '+err.message)}ensureFloorArea();setupPanels();setupWorkspaceUI();renderCatalog();update();$('#importProject').disabled=false;requestAnimationFrame(fit)}
init();
